class Solution {
    public int maximalSquare(char[][] matrix) {
        int rows = matrix.length;
        int columns = matrix[0].length;
        int largestSide = 0;
        for (int top = 0; top < rows; top++) {
            for (int left = 0; left < columns; left++) {
                int limit = Math.min(rows - top, columns - left);
                for (int side = 1; side <= limit; side++) {
                    boolean allOnes = true;
                    for (int row = top; row < top + side && allOnes; row++) {
                        for (int column = left; column < left + side; column++) {
                            if (matrix[row][column] == '0') {
                                allOnes = false;
                                break;
                            }
                        }
                    }
                    if (allOnes) largestSide = Math.max(largestSide, side);
                }
            }
        }
        return largestSide * largestSide;
    }
}

